e,"references":[{"field":"task_id","table":"tasks","org":true,"soft":true}]},{"table":"google_resource_links","label":"Documentregistraties","tab":"documenten","parentField":"entity_id","fields":["name","google_id","resource_type","mime_type","web_url"],"entityField":"entity_type","entityValue":"meeting","capability":"manageOrganization","key":"id","org":true,"soft":false,"actors":["created_by"],"updated":true,"references":[]},{"table":"record_links","label":"Bronlinks","tab":"documenten","parentField":"entity_id","fields":["document_id","label","url","link_type","position"],"entityField":"entity_type","entityValue":"meeting","capability":"manageOrganization","key":"id","org":true,"soft":false,"actors":["created_by"],"updated":true,"references":[{"field":"document_id","table":"document_registry","org":true,"soft":false}]},{"table":"record_relationships","label":"Dossierrelaties","tab":"dossiers","parentField":"source_id","fields":["target_type","target_id","source_type","source_id","relationship_type"],"entityField":"source_type","entityValue":"meeting","capability":"manageOrganization","key":"id","org":true,"soft":false,"actors":["created_by"],"updated":false,"references":[]}],"entity":"meeting","key":"id","org":true,"soft":true,"actors":["created_by"],"updated":true,"references":[]},"inbox":{"table":"inbox_items","label":"Inboxdossier","path":"/app/inbox","capability":"manageInbox","fields":["title","description","source","status","priority","reviewer_id"],"tabs":[{"id":"algemeen","label":"Algemeen"},{"id":"planning","label":"Planning & opvolging"},{"id":"dossiers","label":"Gekoppelde dossiers"},{"id":"documenten","label":"Documenten & koppelingen"}],"collections":[],"key":"id","org":true,"soft":true,"actors":["created_by"],"updated":true,"references":[{"field":"reviewer_id","table":"profiles","org":false,"soft":false}]},"knowledge":{"table":"knowledge_articles","label":"Kennisartikel","path":"/app/kennisbank","capability":"manageOrganization","fields":["title","a